    async def list_templates(
        self,
        sender_id: str,
        *,
        limit: typing.Optional[int] = None,
        offset: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> typing.List[Template]:
        """
        Returns the templates registered on one RCS sender as a bare JSON array, without a total count. Page through them with `limit` and `offset`. `status` is the last stored value; refresh one template with its `/status` endpoint.

        Parameters
        ----------
        sender_id : str
            The `id` (UUID) of the RCS sender that owns the templates. An unknown sender returns `sender not found`.

        limit : typing.Optional[int]
            Maximum number of items to return, from 1 to 100. Defaults to 20; a value outside that range or a non-integer is replaced by the default.

        offset : typing.Optional[int]
            Number of items to skip before the page starts. Defaults to `0`. Pass a whole number of 0 or more.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        typing.List[Template]
            An array of templates. Empty when the sender has none.

        Examples
        --------
        import asyncio

        from vobiz import AsyncVobiz

        client = AsyncVobiz(
            auth_token="YOUR_AUTH_TOKEN",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.sms.rcs_senders.list_templates(
                sender_id="5d7f9b1c-3e5a-4c7e-9f1b-3d5f7a9c1e3b",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.list_templates(
            sender_id, limit=limit, offset=offset, request_options=request_options
        )
        return _response.data

    async def create_template(
        self,
        sender_id: str,
        *,
        template_name: str,
        type: str,
        content: typing.Dict[str, typing.Any],
        request_options: typing.Optional[RequestOptions] = None,
    ) -> Template:
        """
        Registers a message template on an RCS sender with the RCS platform and returns it with status `pending`. `templateName`, `type` and `content` are passed to the platform unchanged, so use the template types and content shapes the RCS platform defines. Call `GET /senders/{senderId}/templates/{templateName}/status` to follow approval. An unknown sender or a platform rejection returns `400`.

        Parameters
        ----------
        sender_id : str
            The `id` (UUID) of the RCS sender that owns the templates. An unknown sender returns `sender not found`.

        template_name : str
            Unique name for the template on this sender. You use it in the path of every template endpoint.

        type : str
            Template type as defined by the RCS platform. It decides which `content` shape the platform expects.

        content : typing.Dict[str, typing.Any]
            Template content as a JSON object in the shape the RCS platform defines for the chosen `type`. Stored and returned exactly as you submit it.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Template
            The new template in status `pending`.

        Examples
        --------
        import asyncio

        from vobiz import AsyncVobiz

        client = AsyncVobiz(
            auth_token="YOUR_AUTH_TOKEN",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.sms.rcs_senders.create_template(
                sender_id="5d7f9b1c-3e5a-4c7e-9f1b-3d5f7a9c1e3b",
                template_name="order-shipped",
                type="TEXT",
                content={
                    "text": "Your order {{orderId}} has shipped and arrives on {{eta}}."
                },
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.create_template(
            sender_id, template_name=template_name, type=type, content=content, request_options=request_options
        )
        return _response.data

